changeSet.sql:

DO $$
DECLARE gl_id BIGINT;
        charge_exists BOOLEAN;
BEGIN
    SELECT id INTO gl_id FROM acc_gl_account WHERE gl_code = '1690952007';
    SELECT EXISTS(SELECT 1 FROM m_charge WHERE name = 'Cargo Manual FNG') INTO charge_exists;
    IF gl_id IS NOT NULL AND NOT charge_exists THEN
        INSERT INTO m_charge
        ("name", currency_code, charge_applies_to_enum, charge_time_enum, charge_calculation_enum, charge_payment_mode_enum, amount, is_penalty, is_active, is_deleted, income_or_liability_account_id)
        VALUES ('Cargo Manual FNG', 'COP', 1, 8, 1009, 0, 1, false, true, false, gl_id);
    END IF;
END
$$;
